    ["<Assistant_Title1>Industrial Matrix</>\n<Assistant_Title2>Achievement Category: </>Leisure - May Manor В· Castle\n<Assistant_Title2>Unlock Condition: </>Four workshops reach Level 6"] = "<Assistant_Title1>РџСЂРѕРјС‹С€Р»РµРЅРЅР°СЏ СЃРµС‚СЊ</>\n<Assistant_Title2>РљР°С‚РµРіРѕСЂРёСЏ РґРѕСЃС‚РёР¶РµРЅРёСЏ: </>РћС‚РґС‹С… вЂ” Р—Р°РјРѕРє\n<Assistant_Title2>РЈСЃР»РѕРІРёРµ СЂР°Р·Р±Р»РѕРєРёСЂРѕРІРєРё: </>РџРѕРІС‹СЃРёС‚СЊ СѓСЂРѕРІРµРЅСЊ С‡РµС‚С‹СЂС‘С… РјР°СЃС‚РµСЂСЃРєРёС… РґРѕ 6-РіРѕ",
